import sys, os, json, math; sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'm2gen')); sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'm3gen'))
from common import *
from numar import decphrase
from rk import RK, rk_pick, rank_of, degphrase
U=ROOT+'/content/m4/u8'
os.makedirs(U, exist_ok=True)
def tw(a,b): a=dict(a); a['twin']=b; return a
def reason(q,pic,ids): return {"t":"reason","q":q,"pic":pic,"opts":[{"id":ids[0],"ok":True},{"id":ids[1]},{"id":ids[2]}]}
MAT=lambda: {"prompt":"mat.01","show":[],"icon":True,"after":"mat.02","facts":[]}
BAG=lambda a,b,la,lb: {"items":[{"icon":a,"label":la},{"icon":b,"label":lb}],"ask":"bag.ask"}
def c8p(**o): return {"kind":"pfpic","c8":o}
RS={'bisPf':['distPerp','tri','asa'],'pbPf':['mid','perpDef','sas'],'bisCon':['conArcV','conArcs','sss'],'perpCon':['conHalf','conSame','conJoin']}
def chain(pf,q=None): return {"t":"prChain","pf":pf,"q":q or "gen.pf.q.chain"}
def why(pf,step,opts,q=None):
    assert opts[0]==RS[pf][step] and len(set(opts))==3, (pf,step,opts)
    return {"t":"prReason","pf":pf,"step":step,"cands":opts,"q":q or "gen.pf.q.reason"}
def r2(v): return math.floor(v*100+0.5)/100   # كـ Math.round في JS تماماً
def r1(v): return math.floor(v*10+0.5)/10
def num(v): return int(v) if float(v).is_integer() else v
T={'sin':{30:.5,45:.71,60:.87},'cos':{30:.87,45:.71,60:.5},'tan':{30:.58,45:1,60:1.73}}
VV=set(); HV=set(); DEGS=set(); RANKS=[]
def half(deg,ask,rot=0,rk=None):   # كـ c8HalfCh (المراجع A لبوابة M4-U7/U8، 1 و15)؛ rot: الضلع الأول مائل (14)
    d,h=deg,deg/2; rk=RK('c8Half') if rk is None else rk
    ch=rk_pick(d,[(h,'bisNoDouble'),(2*d,'bisQuad'),(180-h,'bisSupp')],rk) if ask=='whole' else rk_pick(h,[(d,'bisNoHalf')]+([(d/4,'bisQuarter')] if d%4==0 else [])+[(180-d,'bisSupp'),(2*d,'bisTwice')],rk)
    for v,_ in ch: assert float(v).is_integer(), (deg,ask,ch); DEGS.add(int(v))
    it={"t":"c8Half","deg":deg,"ask":ask,"rk":rk,"q":"gen.c8.q.half."+ask}
    if rot: it["rot"]=rot
    RANKS.append(('c8Half',it,rank_of(ch))); return it
def eqd(deg,at,ns=False,rot=0):   # ns: الرسم ليس بالقياس والزاويتان مكتوبتان (المراجع A لبوابة M4-U7/U8، 20)؛ rot: ضلعٌ مائل (14)
    d={"t":"c8EqDist","deg":deg,"at":at,"q":"gen.c8.q.eqd.ns" if ns else "gen.c8.q.eqd"}
    if ns: d["ns"]=True; DEGS.update([round(deg*at),round(deg*(1-at))])
    if rot: d["rot"]=rot
    return d
def pb(half_,h=None,ask=None,rot=0,rk=None):
    if ask is None: ask='nb' if h is not None else 'mid'
    rk=RK('c8Pb') if rk is None else rk; d={"t":"c8Pb","half":half_,"ask":ask,"rk":rk,"q":"gen.c8.q.pb."+ask}
    if rot: d["rot"]=rot
    if h is not None:
        d["h"]=h; na=int((half_*half_+h*h)**.5); assert na*na==half_*half_+h*h
        ch=rk_pick(na,[(half_+h,'pyAdd'),(half_,'pbHalf'),(h,'pbLeg'),(2*half_,'pbWhole')],rk)
    else: ch=rk_pick(half_,[(2*half_,'midNoHalf')]+([(half_//2,'midQuarter')] if half_%2==0 else [])+[(2*half_-2,'midSub2')],rk)
    assert all(v<=100 and float(v).is_integer() for v,_ in ch), ch   # كلماتها في gen.numw
    RANKS.append(('c8Pb',d,rank_of(ch))); return d
def which(a,b,side,flip=False):
    d={"t":"c8Which","a":a,"b":b,"side":side,"q":"gen.c8.q.which"}
    if flip: d["flip"]=True
    return d
def ratio(a,b,c,fn,flip=False):   # flip: الزاوية المعلّمة عند الرأس العلوي، فالمقابل الأفقي (المراجع A لبوابة M4-U7/U8، 4)
    assert a*a+b*b==c*c, (a,b,c); o,j=(a,b) if flip else (b,a); r={'sin':(o,c),'cos':(j,c),'tan':(o,j)}[fn]; w=r2(r[0]/r[1]); a,b=j,o
    alt={'sin':[(a/c,'trigSwap'),(c/b,'trigFlip'),(b/a,'trigTanFor'),(c/a,'trigOff')],'cos':[(b/c,'trigSwap'),(c/a,'trigFlip'),(a/b,'trigTanFor'),(c/b,'trigOff')],'tan':[(a/b,'trigFlip'),(b/c,'trigHypFor'),(a/c,'trigSwap'),(c/a,'trigOff')]}[fn]
    rk=RK('c8Ratio'); C=rk_pick(w,[(r2(v),e) for v,e in alt],rk,.05)   # ولا مشتّت أقرب من 0.05 (المراجع A لبوابة M4-U7/U8، 15)
    for v,_ in C: VV.add(num(v))
    a,b=(b,a) if flip else (a,b)
    it={"t":"c8Ratio","a":a,"b":b,"hy":c,"fn":fn,"rk":rk,"q":"gen.c8.q.ratio."+fn}
    if flip: it["flip"]=True
    RANKS.append(('c8Ratio',it,rank_of(C))); return it
def table(fn,deg,flip=False):
    w=T[fn][deg]; other=[T['sin'][deg], 45 if deg==45 else T['tan'][90-deg]] if fn=='tan' else [T['cos' if fn=='sin' else 'sin'][deg], .3 if (deg==30 and fn=='sin') else round(deg/100,2)]
    ch=[]
    for v in [w]+other:
        if v not in ch: ch.append(v)
    if len(ch)<3: ch.append(.5 if fn=='tan' else 1)
    for v in ch: VV.add(num(v))
    d={"t":"c8Table","fn":fn,"deg":deg,"q":"gen.c8.q.table."+fn}
    if flip: d["flip"]=True
    return d
def height(dist,deg,rk=None):
    t=T['tan'][deg]; rk=RK('c8Height') if rk is None else rk
    w=r1(dist*t); P=[(r1(dist*T['sin'][deg]),'hSin'),(r1(dist/t),'hDiv'),(r1(dist*T['cos'][deg]),'hCos'),(r1(dist/T['cos'][deg]),'hHyp')]   # خطّ النظر، و«المسافة × الدرجات» احتياطٌ (المراجع A، 15)
    C=rk_pick(w,P if len({v for v,_ in P if v>0 and v!=w})>=2 else P+[(dist*deg,'hAngle')],rk)
    for v,_ in C: HV.add(num(v))
    it={"t":"c8Height","dist":dist,"deg":deg,"rk":rk,"q":"gen.c8.q.height"}; RANKS.append(('c8Height',it,rank_of(C))); return it

