L4={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} مِنْقَلَةٌ وَشَرِيطُ قِيَاسٍ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "tn.01":["chaos","لَا أَحْتَاجُ إِلَى سُلَّمٍ لِأَعْرِفَ ارْتِفَاعَ شَجَرَةٍ!"],
 "tn.02":"نِسْبَةُ المُقَابِلِ إِلَى المُجَاوِرِ نُسَمِّيهَا ظَا، وَهِيَ الظِّلُّ. ظَا خَمْسٍ وَأَرْبَعِينَ وَاحِدٌ، وَظَا ثَلَاثِينَ نَحْوَ ثَمَانِيَةٍ وَخَمْسِينَ جُزْءًا مِنْ مِئَةٍ، وَظَا سِتِّينَ وَاحِدٌ وَثَلَاثَةٌ وَسَبْعُونَ جُزْءًا مِنْ مِئَةٍ.",
 "tn.03":"القَاعِدَةُ: ظَا المُقَابِلُ عَلَى المُجَاوِرِ، فَالمُقَابِلُ هُوَ المُجَاوِرُ فِي ظَا.",
 "sv.01":"مَشْرُوعُ مَسْحِ الارْتِفَاعِ: نَقِفُ عَلَى بُعْدِ اثْنَيْ عَشَرَ مِتْرًا مِنْ شَجَرَةٍ، وَنَقِيسُ زَاوِيَةَ النَّظَرِ إِلَى قِمَّتِهَا بِالمِنْقَلَةِ.",
 "sv.02":"{اِقْرَأْ|اِقْرَئِي} {أَنْتَ|أَنْتِ} الزَّاوِيَةَ عَلَى المِنْقَلَةِ، ثُمَّ ظَا مِنَ الجَدْوَلِ، ثُمَّ {اُحْسُبِ|اُحْسُبِي} الارْتِفَاعَ.",
 "br.01":"حِكَايَةٌ: قَبْلَ أَلْفِ سَنَةٍ تَقْرِيبًا صَعِدَ العَالِمُ أَبُو الرَّيْحَانِ البِيرُونِيُّ جَبَلًا، وَقَاسَ ارْتِفَاعَهُ بِزَوَايَا كَمَا نَفْعَلُ.",
 "br.02":"ثُمَّ نَظَرَ مِنَ القِمَّةِ إِلَى الأُفُقِ، وَقَاسَ زَاوِيَةً صَغِيرَةً جِدًّا، فَحَسَبَ مِنْهَا نِصْفَ قُطْرِ الأَرْضِ، وَقَارَبَ مَا نَعْرِفُهُ اليَوْمَ.",
 "br.03":["compass","زَاوِيَةٌ صَغِيرَةٌ وَجَبَلٌ وَمُثَلَّثٌ قَائِمٌ: هَذَا كُلُّ مَا احْتَاجَهُ لِيَقِيسَ كَوْكَبًا كَامِلًا!"],
 "tb.01":"جَدْوَلُ المَشْرُوعِ بِمَا {وَجَدْتَهُ|وَجَدْتِهِ}: المَسَافَةُ، وَالزَّاوِيَةُ، وَظَا، وَالارْتِفَاعُ بِالمِتْرِ.",
 "tb.02":"وَلِلْإِبْدَاعِ: {اُرْسُمْ|اُرْسُمِي} عَلَى وَرَقَةٍ شَجَرَةً أُخْرَى، {وَاخْتَرْ|وَاخْتَارِي} مَسَافَةً وَزَاوِيَةً، {وَاحْسُبِ|وَاحْسُبِي} ارْتِفَاعَهَا. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "prj.prot":"زَاوِيَةُ النَّظَرِ إِلَى قِمَّةِ الشَّجَرَةِ عَلَى المِنْقَلَةِ: كَمْ دَرَجَةً؟",
 "mat.01":"{قِفْ|قِفِي} أَمَامَ شَجَرَةٍ عَلَى بُعْدٍ {تَقِيسُهُ|تَقِيسِينَهُ} بِشَرِيطِ القِيَاسِ، {وَاقْرَأْ|وَاقْرَئِي} زَاوِيَةَ النَّظَرِ إِلَى قِمَّتِهَا بِالمِنْقَلَةِ. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "prj.intro":"مَسْحُ ارْتِفَاعَاتِ الحَيِّ: كَمِ ارْتِفَاعُ كُلِّ شَجَرَةٍ؟",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: الارْتِفَاعُ هُوَ المَسَافَةُ فِي الزَّاوِيَةِ: عَشَرَةٌ فِي خَمْسٍ وَأَرْبَعِينَ. مَا خَطَؤُهَا؟",
 "pr.r1a":"الزَّاوِيَةُ لَا تُضْرَبُ: نَضْرِبُ المَسَافَةَ فِي ظَا الزَّاوِيَةِ.",
 "pr.r1b":"لَا خَطَأَ: كُلَّمَا كَبُرَتِ الزَّاوِيَةُ ضَرَبْنَا فِيهَا المَسَافَةَ.",
 "pr.r1c":"الخَطَأُ أَنَّهَا ضَرَبَتْ، وَالصَّوَابُ أَنْ تَجْمَعَ الزَّاوِيَةَ وَالمَسَافَةَ.",
 "ch.find":"قَالَتْ فَوْضَى: الشَّجَرَةُ تِسْعُمِئَةِ مِتْرٍ: عِشْرُونَ فِي خَمْسٍ وَأَرْبَعِينَ! كَمِ ارْتِفَاعُهَا حَقًّا؟",
 "ch.after":["chaos","آه! ظَا لَا الزَّاوِيَةُ."],
 "ch.right":"المَسَافَةُ فِي ظَا الزَّاوِيَةِ.",
 "ch.wrong":["chaos","الأَرْقَامُ الكَبِيرَةُ أَجْمَلُ."],
 "ms.1":"لِمَاذَا نَضْرِبُ المَسَافَةَ فِي ظَا الزَّاوِيَةِ لِنَجِدَ الارْتِفَاعَ؟",
 "ms.1a":"ظَا المُقَابِلُ عَلَى المُجَاوِرِ، وَالمُجَاوِرُ المَسَافَةُ، فَنَضْرِبُهَا فِي ظَا.",
 "ms.1b":"الشَّجَرَةُ أَطْوَلُ مِنَ المَسَافَةِ، فَنَضْرِبُ فِي عَدَدٍ لِنُكَبِّرَهَا.",
 "ms.1c":"ظَا اسْمٌ آخَرُ لِلزَّاوِيَةِ نَفْسِهَا بِالدَّرَجَاتِ، فَنَضْرِبُ المَسَافَةَ فِي دَرَجَاتِهَا.",
 "ms.x1":"نَقِفُ عَلَى بُعْدٍ مَعْلُومٍ مِنْ عَمُودِ إِنَارَةٍ، وَنَقِيسُ زَاوِيَةَ النَّظَرِ إِلَى رَأْسِهِ. لِمَاذَا نَسْتَعْمِلُ ظَا لَا جَا؟",
 "ms.x1a":"لِأَنَّنَا نَعْرِفُ المُجَاوِرَ وَنُرِيدُ المُقَابِلَ، وَظَا نِسْبَةُ أَحَدِهِمَا إِلَى الآخَرِ.",
 "ms.x1b":"لِأَنَّ ظَا أَكْبَرُ مِنْ جَا، وَالأَعْمِدَةُ طَوِيلَةٌ فَنَحْتَاجُ عَدَدًا أَكْبَرَ.",
 "ms.x1c":"لِأَنَّ جَا تُسْتَعْمَلُ لِلزَّوَايَا الصَّغِيرَةِ وَحْدَهَا، وَظَا لِلزَّوَايَا الكَبِيرَةِ.",
 "ms.recall":"نَتَذَكَّرُ الخُطُوَاتِ: نَقِيسُ المَسَافَةَ وَزَاوِيَةَ النَّظَرِ، ثُمَّ نَقْرَأُ ظَا مِنَ الجَدْوَلِ، ثُمَّ نَضْرِبُ.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} ظَا وَمَسْحَ الارْتِفَاعِ!",
 "wrap.01":"المَسَافَةُ فِي ظَا: وَنَعْرِفُ الارْتِفَاعَ بِلَا سُلَّمٍ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {اِصْنَعْ|اِصْنَعِي} مَعَ {أَهْلِكَ|أَهْلِكِ} مِنْقَلَةً بِخَيْطٍ وَمِفْتَاحٍ مَرْبُوطٍ فِي مَرْكَزِهَا، {وَاقْرَأْ|وَاقْرَئِي} بِهَا زَاوِيَةَ النَّظَرِ إِلَى سَقْفِ الغُرْفَةِ."],
}
